#include <Arduino.h>
#include <FastLED.h>
#include <Preferences.h>
#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>
#include <BLE2902.h>

// ============================================================
// SHYNETYME BT - ESP32 Arduino 2.x / 3.x BLE-compatible build
// Default: 300 LEDs, GPIO 13, WS2812B/GRB assumption
// ============================================================

#define MAX_LEDS 600
#define DEFAULT_LED_COUNT 300
#define DEFAULT_DATA_PIN 13
#define LED_TYPE WS2812B
#define COLOR_ORDER GRB

#define SERVICE_UUID "78170001-7A32-4B19-913A-5354594D4501"
#define COMMAND_UUID "78170002-7A32-4B19-913A-5354594D4501"
#define STATUS_UUID  "78170003-7A32-4B19-913A-5354594D4501"

CRGB leds[MAX_LEDS];
Preferences prefs;

uint16_t ledCount=DEFAULT_LED_COUNT, activeLedCount=DEFAULT_LED_COUNT;
uint8_t dataPin=DEFAULT_DATA_PIN, activeDataPin=DEFAULT_DATA_PIN;
uint8_t brightness=160, effectSpeed=220, effectIntensity=220;
CRGB foregroundColor(128,0,255), backgroundColor=CRGB::Black;

volatile uint8_t audioLevel=0, audioBass=0, audioMid=0, audioHigh=0;
volatile bool audioBeat=false;

enum EffectMode {
  FX_OFF, FX_SOLID, FX_RAINBOW, FX_COMET, FX_SPARKLE, FX_SCANNER,
  FX_POLICE, FX_BREATHE, FX_CHASE, FX_VU, FX_AUDIO_PULSE, FX_SPECTRUM
};
EffectMode currentEffect=FX_RAINBOW;

uint8_t rainbowHue=0, breathePhase=0;
uint16_t cometPosition=0, chaseOffset=0;
int scannerPosition=0, scannerDirection=1;
bool policeState=false, bluetoothConnected=false;
unsigned long lastPoliceChange=0, lastFrame=0;

BLEServer* bleServer=nullptr;
BLECharacteristic* commandCharacteristic=nullptr;
BLECharacteristic* statusCharacteristic=nullptr;
String deviceName;

// ---------- COLOR ----------
uint32_t packColor(const CRGB& c){ return ((uint32_t)c.r<<16)|((uint32_t)c.g<<8)|c.b; }
CRGB unpackColor(uint32_t v){ return CRGB((v>>16)&0xFF,(v>>8)&0xFF,v&0xFF); }

CRGB hexToColor(String s){
  s.replace("#","");
  if(s.length()!=6) return CRGB::Black;
  return unpackColor(strtoul(s.c_str(),nullptr,16));
}

String colorToHex(const CRGB& c){
  char b[7];
  snprintf(b,sizeof(b),"%02X%02X%02X",c.r,c.g,c.b);
  return String(b);
}

// ---------- SETTINGS ----------
void loadSettings(){
  prefs.begin("shynetyme",true);
  ledCount=prefs.getUShort("ledcount",DEFAULT_LED_COUNT);
  dataPin=prefs.getUChar("pin",DEFAULT_DATA_PIN);
  brightness=prefs.getUChar("bright",160);
  effectSpeed=prefs.getUChar("speed",220);
  effectIntensity=prefs.getUChar("intensity",220);
  foregroundColor=unpackColor(prefs.getUInt("fg",0x8000FF));
  backgroundColor=unpackColor(prefs.getUInt("bg",0x000000));
  prefs.end();
  if(ledCount<1) ledCount=1;
  if(ledCount>MAX_LEDS) ledCount=MAX_LEDS;
  activeLedCount=ledCount;
  activeDataPin=dataPin;
}

void saveSettings(){
  prefs.begin("shynetyme",false);
  prefs.putUShort("ledcount",ledCount);
  prefs.putUChar("pin",dataPin);
  prefs.putUChar("bright",brightness);
  prefs.putUChar("speed",effectSpeed);
  prefs.putUChar("intensity",effectIntensity);
  prefs.putUInt("fg",packColor(foregroundColor));
  prefs.putUInt("bg",packColor(backgroundColor));
  prefs.end();
}

// ---------- LED GPIO ----------
#define ADD_LED_PIN(P) FastLED.addLeds<LED_TYPE,P,COLOR_ORDER>(leds,activeLedCount)

bool configureLEDOutput(uint8_t pin){
  switch(pin){
    case 2: ADD_LED_PIN(2); break;   case 4: ADD_LED_PIN(4); break;
    case 5: ADD_LED_PIN(5); break;   case 12: ADD_LED_PIN(12); break;
    case 13: ADD_LED_PIN(13); break; case 14: ADD_LED_PIN(14); break;
    case 15: ADD_LED_PIN(15); break; case 16: ADD_LED_PIN(16); break;
    case 17: ADD_LED_PIN(17); break; case 18: ADD_LED_PIN(18); break;
    case 19: ADD_LED_PIN(19); break; case 21: ADD_LED_PIN(21); break;
    case 22: ADD_LED_PIN(22); break; case 23: ADD_LED_PIN(23); break;
    case 25: ADD_LED_PIN(25); break; case 26: ADD_LED_PIN(26); break;
    case 27: ADD_LED_PIN(27); break; case 32: ADD_LED_PIN(32); break;
    case 33: ADD_LED_PIN(33); break;
    default:
      dataPin=DEFAULT_DATA_PIN;
      activeDataPin=DEFAULT_DATA_PIN;
      ADD_LED_PIN(DEFAULT_DATA_PIN);
      return false;
  }
  return true;
}

// ---------- EFFECT SELECTION ----------
String effectName(){
  switch(currentEffect){
    case FX_OFF:return "OFF"; case FX_SOLID:return "SOLID"; case FX_RAINBOW:return "RAINBOW";
    case FX_COMET:return "COMET"; case FX_SPARKLE:return "SPARKLE"; case FX_SCANNER:return "SCANNER";
    case FX_POLICE:return "POLICE"; case FX_BREATHE:return "BREATHE"; case FX_CHASE:return "CHASE";
    case FX_VU:return "VU"; case FX_AUDIO_PULSE:return "AUDIO_PULSE"; case FX_SPECTRUM:return "SPECTRUM";
  }
  return "UNKNOWN";
}

void setEffect(String s){
  s.toUpperCase();
  if(s=="OFF") currentEffect=FX_OFF;
  else if(s=="SOLID") currentEffect=FX_SOLID;
  else if(s=="RAINBOW") currentEffect=FX_RAINBOW;
  else if(s=="COMET") currentEffect=FX_COMET;
  else if(s=="SPARKLE") currentEffect=FX_SPARKLE;
  else if(s=="SCANNER") currentEffect=FX_SCANNER;
  else if(s=="POLICE") currentEffect=FX_POLICE;
  else if(s=="BREATHE") currentEffect=FX_BREATHE;
  else if(s=="CHASE") currentEffect=FX_CHASE;
  else if(s=="VU") currentEffect=FX_VU;
  else if(s=="PULSE"||s=="AUDIO_PULSE") currentEffect=FX_AUDIO_PULSE;
  else if(s=="SPECTRUM"||s=="AUDIO_SPECTRUM") currentEffect=FX_SPECTRUM;
}

// ---------- STATUS ----------
String buildStatus(){
  String s;
  s.reserve(220);
  s+="NAME="+deviceName;
  s+=";FX="+effectName();
  s+=";FG="+colorToHex(foregroundColor);
  s+=";BG="+colorToHex(backgroundColor);
  s+=";BRI="+String(brightness);
  s+=";SPD="+String(effectSpeed);
  s+=";INT="+String(effectIntensity);
  s+=";LEDS="+String(activeLedCount);
  s+=";CFGLEDS="+String(ledCount);
  s+=";PIN="+String(activeDataPin);
  s+=";CFGPIN="+String(dataPin);
  s+=";LEVEL="+String(audioLevel);
  s+=";BASS="+String(audioBass);
  s+=";MID="+String(audioMid);
  s+=";HIGH="+String(audioHigh);
  s+=";HEAP="+String(ESP.getFreeHeap());
  s+=";UP="+String(millis()/1000);
  return s;
}

void sendStatus(){
  if(!bluetoothConnected||statusCharacteristic==nullptr) return;
  String s=buildStatus();
  statusCharacteristic->setValue(s.c_str());
  statusCharacteristic->notify();
}

// ---------- COMMANDS ----------
void processSingleCommand(String command){
  command.trim();
  if(!command.length()) return;

  int split=command.indexOf('=');
  String key=(split>=0)?command.substring(0,split):command;
  String value=(split>=0)?command.substring(split+1):"";
  key.trim(); value.trim(); key.toUpperCase();

  if(key=="FX") setEffect(value);
  else if(key=="FG") foregroundColor=hexToColor(value);
  else if(key=="BG") backgroundColor=hexToColor(value);
  else if(key=="BRI"){ brightness=(uint8_t)constrain(value.toInt(),0,255); FastLED.setBrightness(brightness); }
  else if(key=="SPD") effectSpeed=(uint8_t)constrain(value.toInt(),1,255);
  else if(key=="INT") effectIntensity=(uint8_t)constrain(value.toInt(),1,255);
  else if(key=="LEVEL") audioLevel=(uint8_t)constrain(value.toInt(),0,255);
  else if(key=="BASS") audioBass=(uint8_t)constrain(value.toInt(),0,255);
  else if(key=="MID") audioMid=(uint8_t)constrain(value.toInt(),0,255);
  else if(key=="HIGH") audioHigh=(uint8_t)constrain(value.toInt(),0,255);
  else if(key=="BEAT") audioBeat=value.toInt()>0;
  else if(key=="LEDS"){
    long n=value.toInt();
    if(n<1)n=1; if(n>MAX_LEDS)n=MAX_LEDS;
    ledCount=(uint16_t)n;
  }
  else if(key=="PIN"){
    long p=value.toInt();
    if(p<0)p=0; if(p>39)p=39;
    dataPin=(uint8_t)p;
  }
  else if(key=="SAVE") saveSettings();
  else if(key=="STATUS") sendStatus();
  else if(key=="REBOOT"){ saveSettings(); delay(100); ESP.restart(); }
}

void processCommand(String input){
  int start=0;
  while(start<input.length()){
    int end=input.indexOf(';',start);
    if(end<0) end=input.length();
    processSingleCommand(input.substring(start,end));
    start=end+1;
  }
  sendStatus();
}

// ---------- BLE ----------
class ServerCallbacks:public BLEServerCallbacks{
  void onConnect(BLEServer* server) override{
    bluetoothConnected=true;
    Serial.println("BLE connected");
  }
  void onDisconnect(BLEServer* server) override{
    bluetoothConnected=false;
    Serial.println("BLE disconnected");
    delay(100);
    BLEDevice::startAdvertising();
  }
};

class CommandCallbacks:public BLECharacteristicCallbacks{
  void onWrite(BLECharacteristic* characteristic) override{
    String command(characteristic->getValue().c_str());
    if(!command.length()) return;
    Serial.print("BLE: ");
    Serial.println(command);
    processCommand(command);
  }
};

void setupBluetooth(){
  uint64_t chipID=ESP.getEfuseMac();
  char suffix[5];
  snprintf(suffix,sizeof(suffix),"%04X",(uint16_t)(chipID&0xFFFF));
  deviceName="ShyneTyme-"+String(suffix);

  BLEDevice::init(deviceName.c_str());
  bleServer=BLEDevice::createServer();
  bleServer->setCallbacks(new ServerCallbacks());

  BLEService* service=bleServer->createService(SERVICE_UUID);

  commandCharacteristic=service->createCharacteristic(
    COMMAND_UUID,
    BLECharacteristic::PROPERTY_WRITE|BLECharacteristic::PROPERTY_WRITE_NR
  );
  commandCharacteristic->setCallbacks(new CommandCallbacks());

  statusCharacteristic=service->createCharacteristic(
    STATUS_UUID,
    BLECharacteristic::PROPERTY_READ|BLECharacteristic::PROPERTY_NOTIFY
  );
  statusCharacteristic->addDescriptor(new BLE2902());

  String status=buildStatus();
  statusCharacteristic->setValue(status.c_str());

  service->start();

  BLEAdvertising* advertising=BLEDevice::getAdvertising();
  advertising->addServiceUUID(SERVICE_UUID);
  advertising->setScanResponse(true);
  BLEDevice::startAdvertising();

  Serial.print("BLE name: ");
  Serial.println(deviceName);
}

// ---------- EFFECTS ----------
void effectOff(){ fill_solid(leds,activeLedCount,CRGB::Black); }
void effectSolid(){ fill_solid(leds,activeLedCount,foregroundColor); }

void effectRainbow(){
  uint8_t spread=(uint8_t)map(effectIntensity,1,255,1,12);
  uint8_t move=(uint8_t)map(effectSpeed,1,255,1,8);
  fill_rainbow(leds,activeLedCount,rainbowHue,spread);
  rainbowHue+=move;
}

void effectComet(){
  uint8_t fade=(uint8_t)map(effectIntensity,1,255,90,15);
  uint8_t size=(uint8_t)map(effectIntensity,1,255,1,12);
  fadeToBlackBy(leds,activeLedCount,fade);
  for(uint8_t i=0;i<size;i++){
    uint16_t pixel=(cometPosition+activeLedCount-i)%activeLedCount;
    leds[pixel]=foregroundColor;
  }
  if(++cometPosition>=activeLedCount) cometPosition=0;
}

void effectSparkle(){
  fill_solid(leds,activeLedCount,backgroundColor);
  uint8_t count=(uint8_t)map(effectIntensity,1,255,1,30);
  for(uint8_t i=0;i<count;i++) leds[random16(activeLedCount)]=foregroundColor;
}

void effectScanner(){
  fadeToBlackBy(leds,activeLedCount,55);
  uint8_t width=(uint8_t)map(effectIntensity,1,255,1,20);
  if(width>activeLedCount) width=(uint8_t)activeLedCount;
  for(uint8_t i=0;i<width;i++){
    int pixel=scannerPosition+i;
    if(pixel>=0&&pixel<(int)activeLedCount) leds[pixel]=foregroundColor;
  }
  scannerPosition+=scannerDirection;
  int endPosition=(int)activeLedCount-(int)width;
  if(endPosition<0) endPosition=0;
  if(scannerPosition>=endPosition) scannerDirection=-1;
  if(scannerPosition<=0) scannerDirection=1;
}

void effectPolice(){
  uint16_t switchTime=(uint16_t)map(effectSpeed,1,255,500,40);
  if(millis()-lastPoliceChange>=switchTime){
    lastPoliceChange=millis();
    policeState=!policeState;
  }
  uint16_t half=activeLedCount/2;
  for(uint16_t i=0;i<activeLedCount;i++){
    bool first=i<half;
    leds[i]=policeState?(first?CRGB::Red:CRGB::Blue):(first?CRGB::Blue:CRGB::Red);
  }
}

void effectBreathe(){
  CRGB c=foregroundColor;
  c.nscale8_video(sin8(breathePhase));
  fill_solid(leds,activeLedCount,c);
  breathePhase+=(uint8_t)map(effectSpeed,1,255,1,7);
}

void effectChase(){
  fill_solid(leds,activeLedCount,backgroundColor);
  uint8_t spacing=(uint8_t)map(effectIntensity,1,255,20,3);
  for(uint16_t i=0;i<activeLedCount;i++){
    if(((i+chaseOffset)%spacing)<2) leds[i]=foregroundColor;
  }
  chaseOffset++;
}

void effectVU(){
  fill_solid(leds,activeLedCount,backgroundColor);
  uint16_t lit=(uint16_t)map(audioLevel,0,255,0,activeLedCount);
  uint16_t maxPos=(activeLedCount>1)?activeLedCount-1:1;
  for(uint16_t i=0;i<lit;i++){
    uint8_t hue=(uint8_t)map(i,0,maxPos,96,0);
    leds[i]=CHSV(hue,255,255);
  }
}

void effectAudioPulse(){
  uint8_t level=(audioLevel>audioBass)?audioLevel:audioBass;
  if(audioBeat){
    fill_solid(leds,activeLedCount,CRGB::White);
    audioBeat=false;
    return;
  }
  CRGB c=foregroundColor;
  c.nscale8_video(level);
  fill_solid(leds,activeLedCount,c);
}

void effectSpectrum(){
  fill_solid(leds,activeLedCount,backgroundColor);
  uint16_t third=activeLedCount/3;
  if(third==0) third=1;
  uint16_t bassPixels=(uint16_t)map(audioBass,0,255,0,third);
  uint16_t midPixels=(uint16_t)map(audioMid,0,255,0,third);
  uint16_t highStart=third*2;
  uint16_t highSize=(activeLedCount>highStart)?activeLedCount-highStart:0;
  uint16_t highPixels=(uint16_t)map(audioHigh,0,255,0,highSize);

  for(uint16_t i=0;i<bassPixels&&i<activeLedCount;i++) leds[i]=CRGB::Red;
  for(uint16_t i=0;i<midPixels&&third+i<activeLedCount;i++) leds[third+i]=CRGB::Purple;
  for(uint16_t i=0;i<highPixels&&highStart+i<activeLedCount;i++) leds[highStart+i]=CRGB::Blue;
}

void runEffect(){
  switch(currentEffect){
    case FX_OFF:effectOff();break;
    case FX_SOLID:effectSolid();break;
    case FX_RAINBOW:effectRainbow();break;
    case FX_COMET:effectComet();break;
    case FX_SPARKLE:effectSparkle();break;
    case FX_SCANNER:effectScanner();break;
    case FX_POLICE:effectPolice();break;
    case FX_BREATHE:effectBreathe();break;
    case FX_CHASE:effectChase();break;
    case FX_VU:effectVU();break;
    case FX_AUDIO_PULSE:effectAudioPulse();break;
    case FX_SPECTRUM:effectSpectrum();break;
  }
  FastLED.show();
}

// ---------- SETUP / LOOP ----------
void setup(){
  Serial.begin(115200);
  delay(400);
  Serial.println();
  Serial.println("======================");
  Serial.println("SHYNETYME BT");
  Serial.println("======================");

  loadSettings();

  bool pinOK=configureLEDOutput(activeDataPin);
  if(!pinOK) Serial.println("Unsupported GPIO saved. Using GPIO 13.");

  FastLED.setBrightness(brightness);
  FastLED.setMaxPowerInVoltsAndMilliamps(5,2500);
  fill_solid(leds,activeLedCount,CRGB::Black);
  FastLED.show();

  setupBluetooth();

  Serial.print("LEDs: "); Serial.println(activeLedCount);
  Serial.print("GPIO: "); Serial.println(activeDataPin);
  Serial.println("Waiting for Bluetooth controller...");
}

void loop(){
  uint16_t frameInterval=(uint16_t)map(effectSpeed,1,255,80,10);
  if(millis()-lastFrame>=frameInterval){
    lastFrame=millis();
    runEffect();
  }

  static unsigned long lastStatus=0;
  if(bluetoothConnected&&millis()-lastStatus>=2500){
    lastStatus=millis();
    sendStatus();
  }
}
